using System;
using System.Collections.Generic;
using System.Linq;

class Program {
    static void Main() {
        // Array
        int[] numbers = { 10, 20, 30, 40, 50 };
        Console.WriteLine($"Array sum: {numbers.Sum()}");
        Console.WriteLine($"Array avg: {numbers.Average()}");

        // List
        List<string> fruits = new List<string> { "apple", "banana", "cherry" };
        fruits.Add("date");
        Console.WriteLine($"Fruits: {string.Join(", ", fruits)}");
        Console.WriteLine($"Count: {fruits.Count}");

        // Dictionary
        Dictionary<string, int> scores = new Dictionary<string, int> {
            {"Alice", 95}, {"Bob", 87}, {"Charlie", 92}
        };
        Console.WriteLine($"Alice score: {scores["Alice"]}");

        // LINQ
        var evens = numbers.Where(n => n % 20 == 0);
        Console.WriteLine($"Multiples of 20: {string.Join(", ", evens)}");
    }
}

